H.background();
const n = Math.max(1, Math.round(P.n));
const L = 1.0;
const A = 0.8;
const v = H.plot2d({ xMin: 0, xMax: L, yMin: -1.2, yMax: 1.2 });
v.grid(); v.axes();
const k = n * Math.PI / L;
const omega = 2 * Math.PI * 1.0;
const env = Math.cos(omega * t);
const pts = [];
for (let i = 0; i <= 200; i++) {
  const x = L * i / 200;
  pts.push([x, A * Math.sin(k * x) * env]);
}
v.path(pts, { color: H.colors.accent, width: 3 });
const up = [], dn = [];
for (let i = 0; i <= 200; i++) {
  const x = L * i / 200;
  up.push([x, A * Math.sin(k * x)]);
  dn.push([x, -A * Math.sin(k * x)]);
}
v.path(up, { color: H.colors.sub, width: 1, dash: [4, 4] });
v.path(dn, { color: H.colors.sub, width: 1, dash: [4, 4] });
for (let m = 0; m <= n; m++) {
  const xn = m * L / n;
  v.circle(xn, 0, 5, { fill: H.colors.warn });
}
for (let m = 0; m < n; m++) {
  const xa = (m + 0.5) * L / n;
  v.dot(xa, A * Math.sin(k * xa) * env, { r: 5, fill: H.colors.violet });
}
const lam = 2 * L / n;
H.text("Standing wave: y = A sin(kx) cos(wt),  L = n*lambda/2", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Harmonic n = " + n + "   (n nodes shown in orange, antinodes in violet)", 24, 52, { color: H.colors.sub, size: 13 });
H.text("lambda = 2L/n = " + lam.toFixed(2) + " m    nodes = " + (n + 1) + "    antinodes = " + n, 24, 74, { color: H.colors.sub, size: 13 });
